#include <vector>
using namespace std;

class Solution {
public:
    vector<int> getRow(int rowIndex) {
        vector<int> row = {1};

        for (int i = 0; i < rowIndex; i++) {
            // 從右往左更新
            for (int j = row.size() - 1; j > 0; j--) {
                row[j] = row[j] + row[j - 1];
            }
            // 在末尾加 1
            row.push_back(1);
        }

        return row;
    }
};

